/// Validate a tool definition's `x-mcp-header` annotations.
///
/// The revision says a client MUST exclude a tool whose annotations are
/// malformed rather than mirror a header it cannot send correctly. Refused
/// here: an annotation that is not a string, an empty name, a name outside
/// the admitted charset, an annotation on a property whose type is not one
/// SEP-2243 permits (`string`, `integer` or `boolean`; `number` is excluded
/// by name, and `object`, `array` and `null` cannot become one header line),
/// and two properties mapping to the same header name (compared
/// case-insensitively, because HTTP names are).
pub fn validate_tool_header_annotations(tool: &Value) -> Result<(), String> {
    let Some(props) = tool
        .get("inputSchema")
        .and_then(|s| s.get("properties"))
        .and_then(Value::as_object)
    else {
        return Ok(());
    };
    let mut seen: Vec<String> = Vec::new();
    for (property, schema) in props {
        let Some(annotation) = schema.get(X_MCP_HEADER) else { continue };
        let Some(name) = annotation.as_str() else {
            return Err(format!("{property}: {X_MCP_HEADER} must be a string"));
        };
        if !valid_header_name(name) {
            return Err(format!(
                "{property}: {X_MCP_HEADER} {name:?} is not a valid header name (ASCII letters, digits, - and _ only)"
            ));
        }
        match schema.get("type") {
            // A union is admitted when every member other than `null` is a
            // permitted primitive: `["string", "null"]` names an optional
            // string, and a null argument yields no header anyway.
            Some(Value::Array(members)) => {
                let all_permitted = members.iter().all(|m| {
                    matches!(m.as_str(), Some("string") | Some("integer") | Some("boolean") | Some("null"))
                });
                if !all_permitted || members.iter().all(|m| m.as_str() == Some("null")) {
                    return Err(format!(
                        "{property}: type {members:?} cannot carry {X_MCP_HEADER} (string, integer or boolean only)"
                    ));
                }
            }
            Some(Value::String(t)) if t == "string" || t == "integer" || t == "boolean" => {}
            Some(other) => {
                return Err(format!(
                    "{property}: a {other} property cannot carry {X_MCP_HEADER} (string, integer or boolean only)"
                ));
            }
            // Deliberate: an annotated property described only by `$ref`,
            // `enum` or `anyOf` has no type this rule can check, and mirroring
            // an unknown shape into a header is exactly what SEP-2243 forbids.
            None => {
                return Err(format!(
                    "{property}: a property without a type cannot carry {X_MCP_HEADER}"
                ));
            }
        }
        let folded = name.to_ascii_lowercase();
        if seen.contains(&folded) {
            return Err(format!("{property}: header name {name:?} is used by another property"));
        }
        seen.push(folded);
    }
    Ok(())
}

/// Does a header value need the `=?base64?…?=` wrapping?
///
/// Yes for anything an HTTP header cannot carry verbatim: a control character
/// (a tab included), a non-ASCII byte, or leading/trailing whitespace, which
/// field parsing would strip.
fn needs_base64(value: &str) -> bool {
    value.bytes().any(|b| b < 0x20 || b > 0x7e) || value != value.trim()
}

