/// The `Mcp-Param-*` headers for one `tools/call`, from the tool's
/// `inputSchema` and the arguments being sent.
///
/// A property annotated `x-mcp-header` whose argument is present and not null
/// yields one header. Strings ride as they are; numbers and booleans as their
/// JSON text; a value an HTTP header cannot carry verbatim is wrapped as
/// `=?base64?<standard base64>?=`. A null or absent argument yields nothing:
/// SEP-2243 says the header is omitted, not sent empty. Properties without
/// the annotation are never mirrored, whatever their type.
///
/// The caller validates the definition first
/// ([`validate_tool_header_annotations`]); this function assumes it did and
/// skips any annotation it cannot mirror rather than guessing.
pub fn param_headers(input_schema: &Value, arguments: &Value) -> Vec<(String, String)> {
    let mut out = Vec::new();
    let Some(props) = input_schema.get("properties").and_then(Value::as_object) else {
        return out;
    };
    for (property, schema) in props {
        let Some(name) = schema.get(X_MCP_HEADER).and_then(Value::as_str) else { continue };
        if !valid_header_name(name) {
            continue;
        }
        let Some(value) = arguments.get(property) else { continue };
        let text = match value {
            Value::Null | Value::Object(_) | Value::Array(_) => continue,
            Value::String(s) => s.clone(),
            Value::Bool(b) => b.to_string(),
            Value::Number(n) => n.to_string(),
        };
        let encoded = if needs_base64(&text) {
            let mut wrapped = String::from("=?base64?");
            wrapped.push_str(&crate::mcp::b64::encode(text.as_bytes()));
            wrapped.push_str("?=");
            wrapped
        } else {
            text
        };
        let mut header = String::from(HEADER_PARAM_PREFIX);
        header.push_str(&name.to_ascii_lowercase());
        out.push((header, encoded));
    }
    out
}

/// The JSON-RPC messages in one Streamable HTTP response body.
///
/// A server answers a POST either with one JSON body or, as the reference
/// transport does by default, with a `text/event-stream` whose `data:` lines
/// each carry a message (a multi-line `data:` is one message; comment and
/// `event:`/`id:` lines are framing). Both shapes are read here so a caller
/// never has to know which one the server chose. A body that is neither is an
/// error naming the JSON parser's complaint.
pub fn messages_in_body(body: &[u8]) -> Result<Vec<Value>, String> {
    match serde_json::from_slice::<Value>(body) {
        Ok(Value::Array(batch)) => return Ok(batch),
        Ok(one) => return Ok(vec![one]),
        Err(json_error) => {
            let text = core::str::from_utf8(body).map_err(|e| e.to_string())?;
            let mut out = Vec::new();
            let mut data = String::new();
            let flush = |data: &mut String, out: &mut Vec<Value>| -> Result<(), String> {
                if !data.trim().is_empty() {
                    let v: Value = serde_json::from_str(data).map_err(|e| format!("event data is not JSON: {e}"))?;
                    out.push(v);
                }
                data.clear();
                Ok(())
            };
            let mut saw_field = false;
            // The text after the final newline is not a line: "data: x\n" ends with a
            // line terminator, not with the blank line that completes an event.
            let lines: Vec<&str> = text.split('\n').collect();
            let last = lines.len().saturating_sub(1);
            for (at, line) in lines.into_iter().enumerate() {
                if at == last && line.is_empty() {
                    continue;
                }
                let line = line.strip_suffix('\r').unwrap_or(line);
                if line.is_empty() {
                    flush(&mut data, &mut out)?;
                    continue;
                }
                if let Some(rest) = line.strip_prefix("data:") {
                    saw_field = true;
                    if !data.is_empty() {
                        data.push('\n');
                    }
                    data.push_str(rest.strip_prefix(' ').unwrap_or(rest));
                } else if line.starts_with(':')
                    || line.starts_with("event:")
                    || line.starts_with("id:")
                    || line.starts_with("retry:")
                {
                    // A comment or another SSE field. Any other line is not
                    // event-stream framing, so the body is neither JSON nor
                    // SSE and the JSON parser's complaint is the answer.
                } else {
                    return Err(json_error.to_string());
                }
            }
            // An event is complete only at its blank line: data left over at the end
            // is a truncated frame, never a message.
            if !data.trim().is_empty() {
                return Err("the event stream ends inside an event (no closing blank line)".into());
            }
            if !saw_field {
                return Err(json_error.to_string());
            }
            Ok(out)
        }
    }
}

/// What a server's response actually was.
#[derive(Debug, Clone, PartialEq)]
pub enum Outcome {
    /// A final result.
    Complete(Value),
    /// The server needs input first. Answer with [`retry_with_inputs`] on the
    /// ORIGINAL request.
    InputRequired {
        input_requests: Value,
        request_state: Option<String>,
    },
    /// A JSON-RPC error.
    Failed {
        code: i64,
        message: String,
        data: Option<Value>,
    },
}

/// Classify a JSON-RPC response.
///
/// The load-bearing line is the `resultType` default: a server on an earlier
/// revision cannot send the field, so absence means complete. Treating absence as
/// unknown would reject every pre-2026-07-28 response.
///
/// An unrecognised `resultType` is `Failed`, not assumed complete: the
/// specification says a client MUST treat an unknown value as invalid, and a
/// value it does not understand may carry obligations it cannot meet.
pub fn classify(response: &Value) -> Outcome {
    if let Some(err) = response.get("error") {
        return Outcome::Failed {
            code: err
                .get("code")
                .and_then(Value::as_i64)
                .unwrap_or(INTERNAL_ERROR),
            message: err
                .get("message")
                .and_then(Value::as_str)
                .unwrap_or("(no message)")
                .to_string(),
            data: err.get("data").cloned(),
        };
    }
    let Some(result) = response.get("result") else {
        return Outcome::Failed {
            code: INVALID_REQUEST,
            message: "response carried neither result nor error".to_string(),
            data: None,
        };
    };
    match result.get("resultType").and_then(Value::as_str) {
        None | Some(RESULT_COMPLETE) => Outcome::Complete(result.clone()),
        Some(RESULT_INPUT_REQUIRED) => classify_input_required(result),
        Some(other) => Outcome::Failed {
            code: INVALID_PARAMS,
            message: unknown_result_type(other),
            data: None,
        },
    }
}

/// Validate an `InputRequiredResult` against the schema's own rule:
///
/// > At least one of `inputRequests` or `requestState` MUST be present.
///
/// Both shapes are legitimate alone. `inputRequests` alone is the ordinary case
/// (the server wants elicitation or sampling answers). `requestState` alone is
/// **load shedding**: the server defers the work and hands back the state to
/// resume from, asking for nothing. Requiring `inputRequests` would reject that.
///
/// A result with NEITHER is refused rather than repaired. Normalising an absent
/// `inputRequests` to `{}` would hand the caller an actionable MRTR outcome that
/// carries no correlation state, so the retry would arrive at the server with
/// nothing to correlate it to.
///
/// Wrong-shaped fields are refused rather than coerced: an `inputRequests` that is
/// not an object cannot be iterated, and a `requestState` that is not a string
/// cannot be echoed back byte for byte.
fn classify_input_required(result: &Value) -> Outcome {
    let requests = result.get("inputRequests");
    let state = result.get("requestState");

    if let Some(bad) = requests.filter(|v| !v.is_object()) {
        return Outcome::Failed {
            code: INVALID_PARAMS,
            message: shape_error("inputRequests", "an object", bad),
            data: None,
        };
    }
    if let Some(bad) = state.filter(|v| !v.is_string()) {
        return Outcome::Failed {
            code: INVALID_PARAMS,
            message: shape_error("requestState", "a string", bad),
            data: None,
        };
    }
    if requests.is_none() && state.is_none() {
        return Outcome::Failed {
            code: INVALID_PARAMS,
            message: "input_required carried neither inputRequests nor requestState; \
                      the schema requires at least one"
                .to_string(),
            data: None,
        };
    }

    Outcome::InputRequired {
        // Absent means "the server asked for nothing", which is distinct from a
        // malformed result and is why the empty object is only produced HERE,
        // after the at-least-one rule has been satisfied.
        input_requests: requests.cloned().unwrap_or_else(|| serde_json::json!({})),
        request_state: state.and_then(Value::as_str).map(str::to_string),
    }
}

fn shape_error(field: &str, want: &str, got: &Value) -> String {
    let mut s = String::from("input_required field ");
    s.push_str(field);
    s.push_str(" must be ");
    s.push_str(want);
    s.push_str(", got ");
    s.push_str(match got {
        Value::Null => "null",
        Value::Bool(_) => "a boolean",
        Value::Number(_) => "a number",
        Value::String(_) => "a string",
        Value::Array(_) => "an array",
        Value::Object(_) => "an object",
    });
    s
}

fn unknown_result_type(kind: &str) -> String {
    let mut s = String::from("unrecognised resultType ");
    s.push_str(kind);
    s.push_str("; a client must treat this as invalid");
    s
}

/// The server's self-reported identity from a result, if present.
pub fn server_identity(result: &Value) -> Option<Identity> {
    let who = result.get("_meta")?.get(META_SERVER_INFO)?;
    Some(Identity {
        name: who.get("name").and_then(Value::as_str)?.to_string(),
        version: who.get("version").and_then(Value::as_str)?.to_string(),
    })
}

/// A cacheable result's freshness hint in milliseconds, and whether it may be
/// shared across authorization contexts.
///
/// Not-shared is the default when the field is missing: caching a user-specific
/// answer across authorization contexts leaks it, whereas declining to share a
/// public one only costs a re-fetch.
pub fn cache_hint(result: &Value) -> (u64, bool) {
    let ttl = result.get("ttlMs").and_then(Value::as_u64).unwrap_or(0);
    let shared = result.get("cacheScope").and_then(Value::as_str) == Some("public");
    (ttl, shared)
}

/// Re-send `original` carrying the responses a server asked for.
///
/// Everything but `inputResponses` and `requestState` is preserved verbatim. MRTR
/// is defined as a retry of *the same* request, so altering the method or its
/// arguments would produce a different request that merely carries another's
/// state.
///
/// `request_state` is opaque and echoed byte for byte; interpreting it would mean
/// depending on a server's internal representation.
pub fn retry_with_inputs(
    original: &Value,
    input_responses: Value,
    request_state: Option<&str>,
) -> Value {
    let mut out = original.clone();
    let params = out
        .as_object_mut()
        .and_then(|o| o.get_mut("params"))
        .and_then(Value::as_object_mut);
    if let Some(p) = params {
        p.insert("inputResponses".into(), input_responses);
        match request_state {
            Some(s) => {
                p.insert("requestState".into(), Value::String(s.to_string()));
            }
            None => {
                p.remove("requestState");
            }
        }
    }
    out
}

/// A request that passed protocol validation.
#[derive(Debug, Clone)]
pub struct Accepted {
    pub id: Value,
    pub method: String,
    pub params: Value,
    pub capabilities: Value,
    pub client: Option<Identity>,
}

impl Accepted {
    /// Does the request declare `capability`?
    ///
    /// A server MUST NOT rely on a capability the client did not declare, so this
    /// is a presence test and never a default-true.
    pub fn declares(&self, capability: &str) -> bool {
        self.capabilities.get(capability).is_some()
    }
}

/// Why a request was refused, as a JSON-RPC error ready to send.
#[derive(Debug, Clone, PartialEq)]
pub struct Rejection {
    pub code: i64,
    pub message: String,
    pub data: Option<Value>,
}

impl Rejection {
    fn new(code: i64, message: &str, data: Option<Value>) -> Self {
        Self {
            code,
            message: message.to_string(),
            data,
        }
    }

    /// The HTTP status this rejection must be sent with.
    pub fn http_status(&self) -> u16 {
        http_status_for(self.code)
    }

    /// The wire form, for the given request id (null when the id was unreadable).
    pub fn to_response(&self, id: Option<&Value>) -> Value {
        let mut err = Map::new();
        err.insert("code".into(), serde_json::json!(self.code));
        err.insert("message".into(), Value::String(self.message.clone()));
        if let Some(d) = &self.data {
            err.insert("data".into(), d.clone());
        }
        serde_json::json!({
            "jsonrpc": "2.0",
            "id": id.cloned().unwrap_or(Value::Null),
            "error": Value::Object(err),
        })
    }
}

/// Validate an incoming request against this revision.
///
/// The order is load-bearing, because each step needs the previous one to hold:
///
/// 1. JSON-RPC shape — `jsonrpc` is `2.0`, `id` present and non-null, `method`
///    present.
/// 2. Required `_meta`: the protocol version and the client capabilities. Missing
///    either is malformed params, not merely unversioned.
/// 3. The `MCP-Protocol-Version` header equals the body's version. Mismatch is
///    `-32020`, and it is checked BEFORE support because a request whose two
///    declarations disagree has no single version to evaluate.
/// 4. The version is one this server speaks, else `-32022` carrying `supported`
///    and `requested` so the client can choose and retry.
/// 5. SEP-2243's mirrored headers agree with the body: `Mcp-Method` with the
///    method, and `Mcp-Name` with a `tools/call`'s `params.name`. Last, because
///    a request that is not a valid versioned request has nothing to mirror.
///
/// A transport with no headers at all (stdio) skips 3 and 5 — see
/// [`RequestHeaders::none`].
pub fn validate(headers: &RequestHeaders<'_>, body: &Value) -> Result<Accepted, Rejection> {
    if body.get("jsonrpc").and_then(Value::as_str) != Some("2.0") {
        return Err(Rejection::new(INVALID_REQUEST, "jsonrpc must be 2.0", None));
    }
    let id = match body.get("id") {
        None | Some(Value::Null) => {
            return Err(Rejection::new(
                INVALID_REQUEST,
                "a request id is required and must not be null",
                None,
            ))
        }
        // MCP's RequestId is a string or an integer: a boolean, array, object or
        // fraction is no id to answer to.
        Some(v) if v.is_string() || v.is_i64() || v.is_u64() => v.clone(),
        Some(_) => {
            return Err(Rejection::new(
                INVALID_REQUEST,
                "a request id must be a string or an integer",
                None,
            ))
        }
    };
    let Some(method) = body.get("method").and_then(Value::as_str) else {
        return Err(Rejection::new(INVALID_REQUEST, "method is required", None));
    };
    let params = body.get("params").cloned().unwrap_or_else(|| serde_json::json!({}));
    let meta = params.get("_meta");

    let Some(version) = meta
        .and_then(|m| m.get(META_PROTOCOL_VERSION))
        .and_then(Value::as_str)
    else {
        return Err(Rejection::new(
            INVALID_PARAMS,
            "params._meta must carry io.modelcontextprotocol/protocolVersion",
            None,
        ));
    };
    let Some(capabilities) = meta
        .and_then(|m| m.get(META_CLIENT_CAPABILITIES))
        .filter(|c| c.is_object())
        .cloned()
    else {
        return Err(Rejection::new(
            INVALID_PARAMS,
            "params._meta must carry io.modelcontextprotocol/clientCapabilities",
            None,
        ));
    };

    if headers.transport_has_headers() {
        // The header NAME is case-insensitive per HTTP; the VALUE is a protocol
        // version and is compared exactly. A trailing space is a different
        // string, and admitting it would accept a request whose two declarations
        // genuinely differ.
        let Some(h) = headers.protocol_version else {
            return Err(Rejection::new(
                HEADER_MISMATCH,
                "a standard request header required by this revision is missing",
                Some(serde_json::json!({ "header": HEADER_PROTOCOL_VERSION, "body": version })),
            ));
        };
        if h != version {
            return Err(Rejection::new(
                HEADER_MISMATCH,
                "MCP-Protocol-Version header does not match params._meta protocolVersion",
                Some(serde_json::json!({ "header": h, "body": version })),
            ));
        }
    }

    if !SERVER_SUPPORTED_VERSIONS.contains(&version) {
        return Err(Rejection::new(
            UNSUPPORTED_PROTOCOL_VERSION,
            "unsupported protocol version",
            Some(serde_json::json!({ "supported": SERVER_SUPPORTED_VERSIONS, "requested": version })),
        ));
    }

    // SEP-2243. Only on a transport that has headers: on stdio there is nothing
    // to mirror and nothing routing on it.
    if headers.transport_has_headers() {
        mirrored_header_agrees(HEADER_METHOD, headers.method, Some(method))?;
        if let Some(field) = mirrored_field(method) {
            mirrored_header_agrees(HEADER_NAME, headers.name, params.get(field).and_then(Value::as_str))?;
        }
    }

    let client = meta.and_then(|m| m.get(META_CLIENT_INFO)).and_then(|v| {
        Some(Identity {
            name: v.get("name").and_then(Value::as_str)?.to_string(),
            version: v.get("version").and_then(Value::as_str)?.to_string(),
        })
    });

    Ok(Accepted {
        id,
        method: method.to_string(),
        params,
        capabilities,
        client,
    })
}

/// One SEP-2243 mirrored header against the body value it mirrors.
///
/// Three rules, and the third is the one worth stating: a header that is ABSENT
/// while the body carries the value is refused, because this revision makes these
/// headers required. Being lenient about one required field while refusing a
/// request whose `_meta` omits the protocol version would be arbitrary — and an
/// intermediary that expected to route on a header nobody sent has no way to
/// discover that except by mis-routing.
fn mirrored_header_agrees(
    header: &str,
    supplied: Option<&str>,
    body: Option<&str>,
) -> Result<(), Rejection> {
    let Some(expected) = body else {
        // Nothing in the body to mirror. A header that names a value anyway
        // disagrees with the body: an intermediary routed on a name the body
        // does not carry.
        return match supplied.map(header_value).filter(|v| !v.is_empty()) {
            None => Ok(()),
            Some(value) => Err(Rejection::new(
                HEADER_MISMATCH,
                "a standard request header names a value the request body does not carry",
                Some(serde_json::json!({ "header": header, "headerValue": value })),
            )),
        };
    };
    match supplied.map(header_value) {
        Some(value) if unmirror_value(value).as_deref() == Some(expected) => Ok(()),
        Some(value) => Err(Rejection::new(
            HEADER_MISMATCH,
            "a standard request header does not match the request body",
            Some(serde_json::json!({ "header": header, "headerValue": value, "body": expected })),
        )),
        None => Err(Rejection::new(
            HEADER_MISMATCH,
            "a standard request header required by this revision is missing",
            Some(serde_json::json!({ "header": header, "body": expected })),
        )),
    }
}

/// The rejection for a request needing a capability it did not declare.
pub fn missing_capability(required: &[&str]) -> Rejection {
    let mut needed = Map::new();
    for c in required {
        needed.insert((*c).to_string(), serde_json::json!({}));
    }
    Rejection::new(
        MISSING_REQUIRED_CLIENT_CAPABILITY,
        "the request requires a client capability that was not declared",
        Some(serde_json::json!({ "requiredCapabilities": Value::Object(needed) })),
    )
}

/// Stamp a result body as complete, with the server's identity.
pub fn complete(id: &Value, mut body: Map<String, Value>, server: Option<&Identity>) -> Value {
    body.insert("resultType".into(), Value::String(RESULT_COMPLETE.into()));
    if let Some(who) = server {
        let mut meta = Map::new();
        meta.insert(META_SERVER_INFO.into(), who.to_json());
        body.insert("_meta".into(), Value::Object(meta));
    }
    serde_json::json!({ "jsonrpc": "2.0", "id": id.clone(), "result": Value::Object(body) })
}

/// [`complete`], carrying SEP-2549 caching hints.
///
/// Every LIST result should carry them: a client that cannot tell how long a tool
/// list stays valid, or whether it may be shared across authorization contexts,
/// has to choose between re-fetching everything and caching something it should
/// not. `shared` is the same decision [`cache_hint`] reads back, and the same
/// default applies — not-shared is the safe direction, because caching a
/// user-specific answer across contexts leaks it while declining to share a
/// public one costs a re-fetch.
pub fn complete_cacheable(
    id: &Value,
    mut body: Map<String, Value>,
    server: Option<&Identity>,
    ttl_ms: u64,
    shared: bool,
) -> Value {
    body.insert("ttlMs".into(), serde_json::json!(ttl_ms));
    body.insert(
        "cacheScope".into(),
        Value::String(if shared {
            "public".into()
        } else {
            "private".into()
        }),
    );
    complete(id, body, server)
}

/// A `server/discover` result. Required of every server on this revision.
pub fn discover_result(
    id: &Value,
    capabilities: Value,
    instructions: Option<&str>,
    server: Option<&Identity>,
    ttl_ms: u64,
) -> Value {
    let mut body = Map::new();
    body.insert("supportedVersions".into(), serde_json::json!(SERVER_SUPPORTED_VERSIONS));
    body.insert("capabilities".into(), capabilities);
    if let Some(text) = instructions {
        body.insert("instructions".into(), Value::String(text.to_string()));
    }
    body.insert("ttlMs".into(), serde_json::json!(ttl_ms));
    // Discovery describes the server, not the caller, so it is shareable across
    // authorization contexts.
    body.insert("cacheScope".into(), Value::String("public".into()));
    complete(id, body, server)
}

/// Choose a version to speak with a server that advertised `offered`.
///
/// Our preference order wins, not the server's: the list a server sends is
/// unordered as far as the specification is concerned.
pub fn negotiate(offered: &[String]) -> Option<&'static str> {
    SERVER_SUPPORTED_VERSIONS
        .iter()
        .find(|ours| offered.iter().any(|offered| offered == *ours))
        .copied()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn caps() -> Value {
        serde_json::json!({ "elicitation": { "form": {} } })
    }

    fn a_request() -> Value {
        request(
            &serde_json::json!(1),
            M_TOOLS_LIST,
            serde_json::json!({}),
            Some(&Identity::new("buzz", "1.0.0")),
            &caps(),
        )
    }

    /// The headers a correct client sends for [`a_request`].
    fn correct_headers() -> RequestHeaders<'static> {
        RequestHeaders::version(PROTOCOL_VERSION).with_standard(Some(M_TOOLS_LIST), None)
    }

    /// The same, with a different protocol-version header.
    fn headers_versioned(version: &str) -> RequestHeaders<'_> {
        RequestHeaders::version(version).with_standard(Some(M_TOOLS_LIST), None)
    }

    fn code_of(r: Result<Accepted, Rejection>) -> i64 {
        match r {
            Ok(_) => panic!("expected a rejection"),
            Err(e) => e.code,
        }
    }

    #[test]
    fn a_built_request_carries_the_required_meta() {
        let r = a_request();
        let meta = &r["params"]["_meta"];
        assert_eq!(meta[META_PROTOCOL_VERSION], serde_json::json!(PROTOCOL_VERSION));
        assert_eq!(meta[META_CLIENT_CAPABILITIES], caps());
        assert_eq!(meta[META_CLIENT_INFO]["name"], serde_json::json!("buzz"));
        assert_eq!(r["jsonrpc"], serde_json::json!("2.0"));
    }

    #[test]
    fn the_header_and_the_body_must_agree() {
        let r = a_request();
        assert!(validate(&correct_headers(), &r).is_ok());
        // A different version in the header is -32020, and it is caught BEFORE
        // support: there is no single version to evaluate.
        assert_eq!(
            code_of(validate(&headers_versioned(VERSION_2025_06_18), &r)),
            HEADER_MISMATCH
        );
        // Whitespace makes a different string, so a different version.
        assert_eq!(
            code_of(validate(&headers_versioned("2026-07-28 "), &r)),
            HEADER_MISMATCH
        );
    }

    #[test]
    fn a_mirrored_method_header_must_match_the_body() {
        // SEP-2243: the header exists so an intermediary can route without
        // parsing the body, which is exactly why a disagreement is refused — the
        // intermediary routed on one value and the server would act on another.
        let r = a_request();
        let wrong =
            RequestHeaders::version(PROTOCOL_VERSION).with_standard(Some(M_PROMPTS_LIST), None);
        assert_eq!(code_of(validate(&wrong, &r)), HEADER_MISMATCH);

        // A method name is case-SENSITIVE: a folded value routed elsewhere.
        let folded =
            RequestHeaders::version(PROTOCOL_VERSION).with_standard(Some("TOOLS/LIST"), None);
        assert_eq!(code_of(validate(&folded, &r)), HEADER_MISMATCH);

        // Surrounding whitespace is padding, not a different value.
        let padded =
            RequestHeaders::version(PROTOCOL_VERSION).with_standard(Some("  tools/list  "), None);
        assert!(validate(&padded, &r).is_ok());
    }

    #[test]
    fn an_absent_mirrored_header_is_refused_because_the_revision_requires_it() {
        // Being lenient here while refusing a request whose _meta omits the
        // protocol version would be arbitrary — both are required by the same
        // revision. And an intermediary expecting to route on a header nobody
        // sends discovers that only by mis-routing.
        let r = a_request();
        let absent = RequestHeaders::version(PROTOCOL_VERSION);
        assert_eq!(code_of(validate(&absent, &r)), HEADER_MISMATCH);
    }

    #[test]
    fn the_name_header_is_checked_only_where_the_body_has_a_name() {
        // `Mcp-Name` mirrors a tools/call's params.name. A tools/list has no name
        // to mirror, so requiring one would refuse a correct request.
        let list = a_request();
        assert!(validate(&correct_headers(), &list).is_ok());

        let call = request(
            &serde_json::json!(2),
            M_TOOLS_CALL,
            serde_json::json!({ "name": "buzz_search", "arguments": {} }),
            None,
            &caps(),
        );
        let right = RequestHeaders::version(PROTOCOL_VERSION)
            .with_standard(Some(M_TOOLS_CALL), Some("buzz_search"));
        assert!(validate(&right, &call).is_ok());

        let wrong = RequestHeaders::version(PROTOCOL_VERSION)
            .with_standard(Some(M_TOOLS_CALL), Some("some_other_tool"));
        assert_eq!(code_of(validate(&wrong, &call)), HEADER_MISMATCH);

        // Omitted while the body names a tool: refused, same rule as the method.
        let missing =
            RequestHeaders::version(PROTOCOL_VERSION).with_standard(Some(M_TOOLS_CALL), None);
        assert_eq!(code_of(validate(&missing, &call)), HEADER_MISMATCH);
    }

    #[test]
    fn a_name_header_without_its_body_field_is_a_mismatch_and_base64_is_symmetric() {
        // finding_4c044ce371f34d02
        for params in [serde_json::json!({ "arguments": {} }), serde_json::json!({ "name": 7 })] {
            let call = request(&serde_json::json!(3), M_TOOLS_CALL, params, None, &caps());
            let named = RequestHeaders::version(PROTOCOL_VERSION)
                .with_standard(Some(M_TOOLS_CALL), Some("harmless_tool"));
            assert_eq!(code_of(validate(&named, &call)), HEADER_MISMATCH);
        }
        // A name a header cannot carry raw is wrapped, and the wrapped value
        // agrees with the body.
        let headers = request_headers_for(M_TOOLS_CALL, Some("bad\r\nname"));
        let name = headers.iter().find(|(k, _)| k == HEADER_NAME).unwrap().1.clone();
        assert!(name.starts_with("=?base64?"), "{name}");
        let call = request(
            &serde_json::json!(4),
            M_TOOLS_CALL,
            serde_json::json!({ "name": "bad\r\nname", "arguments": {} }),
            None,
            &caps(),
        );
        let wrapped = RequestHeaders::version(PROTOCOL_VERSION).with_standard(Some(M_TOOLS_CALL), Some(&name));
        assert!(validate(&wrapped, &call).is_ok());
    }

    #[test]
    fn a_header_mismatch_is_a_400() {
        let r = a_request();
        let e = validate(&headers_versioned(VERSION_2025_06_18), &r).expect_err("rejection");
        assert_eq!(e.http_status(), 400);
        let wire = e.to_response(Some(&serde_json::json!(1)));
        assert_eq!(wire["error"]["code"], serde_json::json!(HEADER_MISMATCH));
        assert_eq!(wire["id"], serde_json::json!(1));
    }

    #[test]
    fn method_not_found_is_a_404() {
        // SEP-2575 states it outright: a server that does not implement a method
        // MUST answer 404 together with -32601. An intermediary reads the status,
        // not the body, so 200-with-an-error-inside is not equivalent.
        assert_eq!(http_status_for(METHOD_NOT_FOUND), 404);
        let r = Rejection {
            code: METHOD_NOT_FOUND,
            message: "nope".into(),
            data: None,
        };
        assert_eq!(r.http_status(), 404);
        // And the other codes are unchanged.
        assert_eq!(http_status_for(HEADER_MISMATCH), 400);
        assert_eq!(http_status_for(INTERNAL_ERROR), 200);
    }

    #[test]
    fn stdio_has_no_headers_so_those_checks_do_not_apply() {
        // No protocol-version header means no headers at all, so neither the
        // version comparison nor SEP-2243's mirroring applies — there is nothing
        // between the client and the server routing on them.
        assert!(validate(&RequestHeaders::none(), &a_request()).is_ok());
        let call = request(
            &serde_json::json!(3),
            M_TOOLS_CALL,
            serde_json::json!({ "name": "buzz_search" }),
            None,
            &caps(),
        );
        assert!(validate(&RequestHeaders::none(), &call).is_ok());
    }

    /// F486: on HTTP the version header is required. Before, omitting it made
    /// the request look like stdio and switched every header rule off.
    #[test]
    fn http_without_the_version_header_is_refused() {
        let refused = validate(&RequestHeaders::http(None, Some(M_TOOLS_LIST), None), &a_request())
            .expect_err("refused");
        assert_eq!(refused.code, HEADER_MISMATCH);
        assert_eq!(refused.http_status(), 400);
        let refused = validate(&RequestHeaders::http(None, None, None), &a_request()).expect_err("refused");
        assert_eq!(refused.code, HEADER_MISMATCH);
        // All three present and agreeing is accepted.
        assert!(validate(
            &RequestHeaders::http(Some(PROTOCOL_VERSION), Some(M_TOOLS_LIST), None),
            &a_request()
        )
        .is_ok());
    }

    /// F486: the exact desynchronisation SEP-2243 exists to stop. A client
    /// drops `MCP-Protocol-Version`, sends `Mcp-Method: tools/list` and a
    /// harmless `Mcp-Name`, and the body calls a different tool. Even a caller
    /// that did not mark the transport as HTTP refuses it, because a mirrored
    /// header is present.
    #[test]
    fn dropping_the_version_header_does_not_switch_the_mirrored_checks_off() {
        let call = request(
            &serde_json::json!(4),
            M_TOOLS_CALL,
            serde_json::json!({ "name": "delete_everything" }),
            None,
            &caps(),
        );
        let desynced = RequestHeaders {
            http: false,
            protocol_version: None,
            method: Some(M_TOOLS_LIST),
            name: Some("harmless_tool"),
        };
        assert_eq!(validate(&desynced, &call).expect_err("refused").code, HEADER_MISMATCH);
        let name_only = RequestHeaders {
            name: Some("harmless_tool"),
            ..RequestHeaders::none()
        };
        assert_eq!(validate(&name_only, &call).expect_err("refused").code, HEADER_MISMATCH);
        // On HTTP, with the version present, the mismatch is refused as before.
        let versioned = RequestHeaders::http(Some(PROTOCOL_VERSION), Some(M_TOOLS_CALL), Some("harmless_tool"));
        assert_eq!(validate(&versioned, &call).expect_err("refused").code, HEADER_MISMATCH);
    }

    #[test]
    fn the_required_meta_is_required() {
        let mut r = a_request();
        r["params"]["_meta"]
            .as_object_mut()
            .expect("meta")
            .remove(META_CLIENT_CAPABILITIES);
        assert_eq!(code_of(validate(&correct_headers(), &r)), INVALID_PARAMS);

        let mut r = a_request();
        r["params"]["_meta"]
            .as_object_mut()
            .expect("meta")
            .remove(META_PROTOCOL_VERSION);
        assert_eq!(code_of(validate(&correct_headers(), &r)), INVALID_PARAMS);
    }

    #[test]
    fn an_unsupported_version_names_what_is_supported() {
        let mut r = a_request();
        r["params"]["_meta"][META_PROTOCOL_VERSION] = serde_json::json!("1999-01-01");
        let e = validate(&headers_versioned("1999-01-01"), &r).expect_err("rejection");
        assert_eq!(e.code, UNSUPPORTED_PROTOCOL_VERSION);
        assert_eq!(e.http_status(), 400);
        let data = e.data.expect("this code requires data");
        assert_eq!(data["requested"], serde_json::json!("1999-01-01"));
        assert_eq!(data["supported"], serde_json::json!(SERVER_SUPPORTED_VERSIONS));
    }

    #[test]
    fn a_null_id_is_refused() {
        // JSON-RPC permits it; MCP does not.
        let mut r = a_request();
        r["id"] = Value::Null;
        assert_eq!(code_of(validate(&correct_headers(), &r)), INVALID_REQUEST);
    }

    #[test]
    fn an_absent_result_type_means_complete() {
        // THE backward-compatibility hinge: a 2025-06-18 server cannot send the
        // field, so reading absence as an error rejects every legacy response.
        let legacy = serde_json::json!({ "jsonrpc": "2.0", "id": 1, "result": { "tools": [] } });
        assert!(matches!(classify(&legacy), Outcome::Complete(_)));
    }

    #[test]
    fn an_unknown_result_type_is_invalid_not_assumed_complete() {
        let r = serde_json::json!({ "jsonrpc": "2.0", "id": 1, "result": { "resultType": "something_new" } });
        match classify(&r) {
            Outcome::Failed { code, message, .. } => {
                assert_eq!(code, INVALID_PARAMS);
                assert!(message.contains("something_new"), "{message}");
            }
            _ => panic!("an unknown resultType must not be treated as complete"),
        }
    }

    #[test]
    fn input_required_is_answered_by_a_verbatim_retry() {
        let original = a_request();
        let response = serde_json::json!({
            "jsonrpc": "2.0",
            "id": 1,
            "result": {
                "resultType": RESULT_INPUT_REQUIRED,
                "inputRequests": { "a": { "method": "elicitation/create" } },
                "requestState": "opaque-blob"
            }
        });
        let (requests, state) = match classify(&response) {
            Outcome::InputRequired {
                input_requests,
                request_state,
            } => (input_requests, request_state),
            _ => panic!("expected input_required"),
        };
        assert!(requests.get("a").is_some());
        assert_eq!(state.as_deref(), Some("opaque-blob"));

        let retry = retry_with_inputs(
            &original,
            serde_json::json!({ "a": { "action": "accept" } }),
            state.as_deref(),
        );
        // The SAME request: method, id and _meta untouched.
        assert_eq!(retry["method"], original["method"]);
        assert_eq!(retry["id"], original["id"]);
        assert_eq!(retry["params"]["_meta"], original["params"]["_meta"]);
        assert_eq!(retry["params"]["requestState"], serde_json::json!("opaque-blob"));
        assert_eq!(
            retry["params"]["inputResponses"]["a"]["action"],
            serde_json::json!("accept")
        );
    }

    #[test]
    fn a_retry_without_state_carries_none() {
        let retry = retry_with_inputs(&a_request(), serde_json::json!({}), None);
        assert!(retry["params"].get("requestState").is_none());
    }

    /// An `input_required` result carrying only the fields named.
    fn input_required(fields: Value) -> Value {
        let mut result = match fields {
            Value::Object(m) => m,
            _ => Map::new(),
        };
        result.insert("resultType".into(), serde_json::json!(RESULT_INPUT_REQUIRED));
        serde_json::json!({ "jsonrpc": "2.0", "id": 1, "result": Value::Object(result) })
    }

    fn failure_message(response: &Value) -> String {
        match classify(response) {
            Outcome::Failed { message, .. } => message,
            _ => panic!("expected a failure"),
        }
    }

    #[test]
    fn request_state_alone_is_valid_because_that_is_load_shedding() {
        // The server defers the work and asks for nothing, handing back the state
        // to resume from. Requiring inputRequests would reject this.
        let r = input_required(serde_json::json!({ "requestState": "resume-me" }));
        match classify(&r) {
            Outcome::InputRequired {
                input_requests,
                request_state,
            } => {
                assert_eq!(input_requests, serde_json::json!({}), "nothing was asked for");
                assert_eq!(request_state.as_deref(), Some("resume-me"));
            }
            _ => panic!("request state alone must be accepted"),
        }
    }

    #[test]
    fn input_requests_alone_is_valid() {
        let r = input_required(serde_json::json!({ "inputRequests": { "a": { "method": "x" } } }));
        assert!(matches!(classify(&r), Outcome::InputRequired { .. }));
    }

    #[test]
    fn neither_field_is_a_failure_not_a_repaired_result() {
        // Normalising this would hand the caller an actionable MRTR outcome with
        // no correlation state, and the retry would reach the server with nothing
        // to tie it to.
        let msg = failure_message(&input_required(serde_json::json!({})));
        assert!(msg.contains("at least one"), "{msg}");
    }

    #[test]
    fn wrong_shaped_mrtr_fields_are_refused_not_coerced() {
        // A non-object cannot be iterated; a non-string cannot be echoed back.
        let msg = failure_message(&input_required(serde_json::json!({ "inputRequests": [] })));
        assert!(msg.contains("inputRequests"), "{msg}");
        assert!(msg.contains("an array"), "{msg}");

        let msg = failure_message(&input_required(serde_json::json!({ "requestState": 7 })));
        assert!(msg.contains("requestState"), "{msg}");
        assert!(msg.contains("a number"), "{msg}");

        // And a wrong shape is refused even when the other field would satisfy
        // the at-least-one rule on its own.
        let both = input_required(serde_json::json!({ "inputRequests": 1, "requestState": "ok" }));
        assert!(matches!(classify(&both), Outcome::Failed { .. }));
    }

    #[test]
    fn an_error_response_classifies_as_failed() {
        let r = serde_json::json!({
            "jsonrpc": "2.0",
            "id": 1,
            "error": {
                "code": UNSUPPORTED_PROTOCOL_VERSION,
                "message": "nope",
                "data": { "supported": [PROTOCOL_VERSION] }
            }
        });
        match classify(&r) {
            Outcome::Failed { code, data, .. } => {
                assert_eq!(code, UNSUPPORTED_PROTOCOL_VERSION);
                assert_eq!(data.expect("data")["supported"], serde_json::json!([PROTOCOL_VERSION]));
            }
            _ => panic!("expected a failure"),
        }
    }

    #[test]
    fn a_response_with_neither_result_nor_error_is_failed() {
        assert!(matches!(
            classify(&serde_json::json!({ "jsonrpc": "2.0", "id": 1 })),
            Outcome::Failed { .. }
        ));
    }

    #[test]
    fn capabilities_are_never_assumed() {
        let accepted = validate(&correct_headers(), &a_request()).expect("valid");
        assert!(accepted.declares("elicitation"));
        assert!(!accepted.declares("sampling"));
        let r = missing_capability(&["sampling"]);
        assert_eq!(r.code, MISSING_REQUIRED_CLIENT_CAPABILITY);
        assert!(r.data.expect("data")["requiredCapabilities"]["sampling"].is_object());
    }

    #[test]
    fn discover_advertises_exactly_what_we_speak() {
        let d = discover_result(
            &serde_json::json!(7),
            serde_json::json!({ "tools": {} }),
            Some("a relay"),
            Some(&Identity::new("buzz", "1.0.0")),
            60_000,
        );
        let r = &d["result"];
        assert_eq!(r["resultType"], serde_json::json!(RESULT_COMPLETE));
        assert_eq!(r["supportedVersions"], serde_json::json!([PROTOCOL_VERSION]));
        assert_eq!(r["ttlMs"], serde_json::json!(60_000));
        assert_eq!(
            server_identity(r).expect("identity"),
            Identity::new("buzz", "1.0.0")
        );
        assert_eq!(cache_hint(r), (60_000, true));
    }

    #[test]
    fn a_missing_cache_scope_is_not_shared() {
        // Sharing a user-specific answer across authorization contexts leaks it.
        assert_eq!(cache_hint(&serde_json::json!({ "ttlMs": 5 })), (5, false));
    }

    #[test]
    fn negotiation_prefers_our_order_and_can_fail() {
        let both = vec![VERSION_2025_06_18.to_string(), PROTOCOL_VERSION.to_string()];
        assert_eq!(negotiate(&both), Some(PROTOCOL_VERSION));
        assert_eq!(negotiate(&[VERSION_2025_06_18.to_string()]), None);
        assert_eq!(negotiate(&[]), None);
    }

    #[test]
    fn a_list_result_carries_its_caching_hints() {
        // SEP-2549. Without them a client must choose between re-fetching a tool
        // list on every call and caching something it may not be allowed to keep.
        let mut body = Map::new();
        body.insert("tools".into(), serde_json::json!([]));
        let r = complete_cacheable(
            &serde_json::json!(1),
            body,
            Some(&Identity::new("buzz", "1.0.0")),
            60_000,
            false,
        );
        let result = &r["result"];
        assert_eq!(result["resultType"], serde_json::json!(RESULT_COMPLETE));
        assert_eq!(result["ttlMs"], serde_json::json!(60_000));
        assert_eq!(result["cacheScope"], serde_json::json!("private"));
        // And it reads back through this module's own accessor, not-shared.
        assert_eq!(cache_hint(result), (60_000, false));

        let mut body = Map::new();
        body.insert("tools".into(), serde_json::json!([]));
        let shared = complete_cacheable(&serde_json::json!(2), body, None, 1_000, true);
        assert_eq!(cache_hint(&shared["result"]), (1_000, true));
    }

    #[test]
    fn the_transport_headers_agree_with_what_a_request_declares() {
        // The pair a correct client sends must validate together, including the
        // SEP-2243 mirror — a client that built one and not the other would be
        // refused by a conformant server.
        let headers = request_headers_for(M_TOOLS_LIST, None);
        let value_of = |name: &str| {
            headers
                .iter()
                .find(|(k, _)| k.eq_ignore_ascii_case(name))
                .map(|(_, v)| v.clone())
        };
        let version = value_of(HEADER_PROTOCOL_VERSION).expect("the version header is mandatory");
        assert_eq!(version, PROTOCOL_VERSION);
        let method = value_of(HEADER_METHOD).expect("SEP-2243 requires the method header");
        assert_eq!(method, M_TOOLS_LIST);
        assert!(value_of(HEADER_NAME).is_none(), "a listing names no tool");

        let sent = RequestHeaders::version(&version).with_standard(Some(&method), None);
        assert!(validate(&sent, &a_request()).is_ok());

        // And a tools/call carries the name.
        let call_headers = request_headers_for(M_TOOLS_CALL, Some("buzz_search"));
        assert!(call_headers
            .iter()
            .any(|(k, v)| k.eq_ignore_ascii_case(HEADER_NAME) && v == "buzz_search"));
    }

    fn tool(props: Value) -> Value {
        serde_json::json!({ "name": "t", "inputSchema": { "type": "object", "properties": props } })
    }

    #[test]
    fn a_body_is_read_as_json_or_as_an_event_stream() {
        let one = messages_in_body(br#"{"jsonrpc":"2.0","id":1,"result":{}}"#).unwrap();
        assert_eq!(one.len(), 1);
        let batch = messages_in_body(br#"[{"jsonrpc":"2.0","id":1,"result":{}},{"jsonrpc":"2.0","id":2,"result":{}}]"#).unwrap();
        assert_eq!(batch.len(), 2);
        let sse = b"event: message\r\ndata: {\"jsonrpc\":\"2.0\",\"id\":7,\r\ndata:  \"result\":{}}\r\n\r\n: keep-alive\r\n\r\n";
        let msgs = messages_in_body(sse).unwrap();
        assert_eq!(msgs.len(), 1);
        assert_eq!(msgs[0]["id"], serde_json::json!(7));
        assert!(messages_in_body(b"<html>oops").is_err());
        assert!(messages_in_body(b"data: not json\n\n").is_err());
        // finding_2a2ce058eb8f1868: a frame cut before its blank line is not a message.
        assert!(messages_in_body(b"data: {\"jsonrpc\":\"2.0\",\"id\":7,\"result\":{}}\n").is_err());
        // Colons alone do not make an event stream.
        assert!(messages_in_body(b"Error: upstream timeout\n").is_err());
        assert!(messages_in_body(b"<title>502: Bad Gateway</title>").is_err());
    }

    #[test]
    fn an_optional_annotated_property_is_admitted() {
        assert!(validate_tool_header_annotations(&tool(serde_json::json!({
            "region": { "type": ["string", "null"], "x-mcp-header": "Region" }
        }))).is_ok());
        assert!(validate_tool_header_annotations(&tool(serde_json::json!({
            "data": { "type": ["object", "null"], "x-mcp-header": "Data" }
        }))).is_err());
        assert!(validate_tool_header_annotations(&tool(serde_json::json!({
            "n": { "type": ["null"], "x-mcp-header": "Nil" }
        }))).is_err());
        assert!(validate_tool_header_annotations(&tool(serde_json::json!({
            "e": { "enum": ["a", "b"], "x-mcp-header": "E" }
        }))).is_err(), "typeless annotated properties are refused on purpose");
    }

    #[test]
    fn annotated_parameters_are_mirrored_with_the_encoding_the_value_needs() {
        let schema = serde_json::json!({
            "type": "object",
            "properties": {
                "region": { "type": "string", "x-mcp-header": "Region" },
                "priority": { "type": "integer", "x-mcp-header": "Priority" },
                "verbose": { "type": "boolean", "x-mcp-header": "Verbose" },
                "method_val": { "type": "string", "x-mcp-header": "Method" },
                "empty_val": { "type": "string", "x-mcp-header": "EmptyVal" },
                "non_ascii": { "type": "string", "x-mcp-header": "NonAscii" },
                "padded": { "type": "string", "x-mcp-header": "Padded" },
                "tabbed": { "type": "string", "x-mcp-header": "Tabbed" },
                "float_val": { "type": "number" },
                "query": { "type": "string" }
            }
        });
        let args = serde_json::json!({
            "region": "us-west1", "priority": 42, "verbose": false, "method_val": "test-method",
            "empty_val": "", "non_ascii": "Hello, 世界", "padded": " padded ", "tabbed": "\tindented",
            "float_val": 3.14159, "query": "SELECT * FROM users", "absent_annotation": "x"
        });
        let headers = param_headers(&schema, &args);
        let get = |name: &str| headers.iter().find(|(k, _)| k == name).map(|(_, v)| v.as_str());
        assert_eq!(get("mcp-param-region"), Some("us-west1"));
        assert_eq!(get("mcp-param-priority"), Some("42"));
        assert_eq!(get("mcp-param-verbose"), Some("false"));
        // `Method` mirrors into Mcp-Param-Method, never into Mcp-Method.
        assert_eq!(get("mcp-param-method"), Some("test-method"));
        assert!(!headers.iter().any(|(k, _)| k == HEADER_METHOD));
        assert_eq!(get("mcp-param-emptyval"), Some(""));
        assert_eq!(get("mcp-param-nonascii"), Some("=?base64?SGVsbG8sIOS4lueVjA==?="));
        assert_eq!(get("mcp-param-padded"), Some("=?base64?IHBhZGRlZCA=?="));
        assert_eq!(get("mcp-param-tabbed"), Some("=?base64?CWluZGVudGVk?="));
        // Unannotated properties are never mirrored, whatever their type.
        assert!(get("mcp-param-float_val").is_none() && get("mcp-param-query").is_none());
        assert_eq!(headers.len(), 8);
    }

    #[test]
    fn a_null_or_absent_annotated_argument_yields_no_header() {
        let schema = serde_json::json!({ "type": "object", "properties": {
            "verbose": { "type": "boolean", "x-mcp-header": "Verbose" },
            "region": { "type": "string", "x-mcp-header": "Region" }
        }});
        let headers = param_headers(&schema, &serde_json::json!({ "verbose": null }));
        assert!(headers.is_empty(), "{headers:?}");
    }

    #[test]
    fn tool_definitions_with_malformed_header_annotations_are_refused() {
        assert!(validate_tool_header_annotations(&tool(serde_json::json!({
            "region": { "type": "string", "x-mcp-header": "Region" },
            "n": { "type": "integer", "x-mcp-header": "N" },
            "plain": { "type": "number" }
        }))).is_ok(), "valid definitions pass, unannotated numbers included");
        assert!(validate_tool_header_annotations(&serde_json::json!({ "name": "no-schema" })).is_ok());
        for (why, props) in [
            ("empty", serde_json::json!({ "v": { "type": "string", "x-mcp-header": "" } })),
            ("object type", serde_json::json!({ "d": { "type": "object", "x-mcp-header": "Data" } })),
            ("array type", serde_json::json!({ "i": { "type": "array", "items": { "type": "string" }, "x-mcp-header": "Items" } })),
            ("null type", serde_json::json!({ "n": { "type": "null", "x-mcp-header": "Nil" } })),
            ("number type", serde_json::json!({ "s": { "type": "number", "x-mcp-header": "Score" } })),
            ("non-string annotation", serde_json::json!({ "s": { "type": "string", "x-mcp-header": 42 } })),
            ("duplicate", serde_json::json!({ "a": { "type": "string", "x-mcp-header": "Region" }, "b": { "type": "string", "x-mcp-header": "Region" } })),
            ("duplicate differing in case", serde_json::json!({ "a": { "type": "string", "x-mcp-header": "Region" }, "b": { "type": "string", "x-mcp-header": "REGION" } })),
            ("space", serde_json::json!({ "v": { "type": "string", "x-mcp-header": "Bad Name" } })),
            ("colon", serde_json::json!({ "v": { "type": "string", "x-mcp-header": "Bad:Name" } })),
            ("non-ascii", serde_json::json!({ "v": { "type": "string", "x-mcp-header": "Región" } })),
            ("control char", serde_json::json!({ "v": { "type": "string", "x-mcp-header": "Bad\nName" } })),
        ] {
            assert!(validate_tool_header_annotations(&tool(props)).is_err(), "{why} must be refused");
        }
    }
}
